Nice — here’s a clean, complete Binary Search Tree (BST) implementation in C. It includes insertion, searching, deletion, traversal (inorder/preorder/postorder), finding min/max, and computing tree height. Copy-paste into a single `.c` file and compile with `gcc bst.c -o bst`.

```c
// bst.c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    struct Node *left;
    struct Node *right;
} Node;

/* Create a new node */
Node* newNode(int item) {
    Node* temp = (Node*)malloc(sizeof(Node));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    temp->key = item;
    temp->left = temp->right = NULL;
    return temp;
}

/* Insert a key into BST */
Node* insert(Node* root, int key) {
    if (root == NULL) return newNode(key);

    if (key < root->key)
        root->left = insert(root->left, key);
    else if (key > root->key)
        root->right = insert(root->right, key);
    // if key == root->key, do nothing (no duplicates). Change behaviour if you want duplicates.
    return root;
}

/* Search a key in BST: returns 1 if found, 0 otherwise */
int search(Node* root, int key) {
    if (root == NULL) return 0;
    if (key == root->key) return 1;
    else if (key < root->key) return search(root->left, key);
    else return search(root->right, key);
}

/* Find node with minimum key (leftmost) */
Node* minValueNode(Node* node) {
    Node* current = node;
    while (current && current->left != NULL)
        current = current->left;
    return current;
}

/* Find node with maximum key (rightmost) */
Node* maxValueNode(Node* node) {
    Node* current = node;
    while (current && current->right != NULL)
        current = current->right;
    return current;
}

/* Delete a key from BST */
Node* deleteNode(Node* root, int key) {
    if (root == NULL) return root;

    if (key < root->key)
        root->left = deleteNode(root->left, key);
    else if (key > root->key)
        root->right = deleteNode(root->right, key);
    else {
        // node with only one child or no child
        if (root->left == NULL) {
            Node* temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            Node* temp = root->left;
            free(root);
            return temp;
        }

        // node with two children: get inorder successor (smallest in right subtree)
        Node* temp = minValueNode(root->right);

        // copy inorder successor's content to this node
        root->key = temp->key;

        // delete the inorder successor
        root->right = deleteNode(root->right, temp->key);
    }
    return root;
}

/* Inorder traversal (sorted order) */
void inorder(Node* root) {
    if (root != NULL) {
        inorder(root->left);
        printf("%d ", root->key);
        inorder(root->right);
    }
}

/* Preorder traversal */
void preorder(Node* root) {
    if (root != NULL) {
        printf("%d ", root->key);
        preorder(root->left);
        preorder(root->right);
    }
}

/* Postorder traversal */
void postorder(Node* root) {
    if (root != NULL) {
        postorder(root->left);
        postorder(root->right);
        printf("%d ", root->key);
    }
}

/* Height of the tree (number of nodes on longest path) */
int height(Node* node) {
    if (node == NULL) return 0;
    int lh = height(node->left);
    int rh = height(node->right);
    return (lh > rh ? lh : rh) + 1;
}

/* Free entire tree */
void freeTree(Node* root) {
    if (root == NULL) return;
    freeTree(root->left);
    freeTree(root->right);
    free(root);
}

/* Simple interactive demo / menu */
int main() {
    Node* root = NULL;
    int choice, val;

    while (1) {
        printf("\n--- BST Menu ---\n");
        printf("1. Insert\n2. Search\n3. Delete\n4. Inorder (sorted)\n5. Preorder\n6. Postorder\n7. Find Min\n8. Find Max\n9. Height\n0. Exit\n");
        printf("Choice: ");
        if (scanf("%d", &choice) != 1) {
            // clear input and continue
            while (getchar() != '\n');
            printf("Invalid input\n");
            continue;
        }

        switch (choice) {
            case 1:
                printf("Value to insert: ");
                scanf("%d", &val);
                root = insert(root, val);
                break;
            case 2:
                printf("Value to search: ");
                scanf("%d", &val);
                printf(search(root, val) ? "Found\n" : "Not found\n");
                break;
            case 3:
                printf("Value to delete: ");
                scanf("%d", &val);
                root = deleteNode(root, val);
                break;
            case 4:
                printf("Inorder: ");
                inorder(root);
                printf("\n");
                break;
            case 5:
                printf("Preorder: ");
                preorder(root);
                printf("\n");
                break;
            case 6:
                printf("Postorder: ");
                postorder(root);
                printf("\n");
                break;
            case 7:
                if (root) printf("Min: %d\n", minValueNode(root)->key);
                else printf("Tree is empty\n");
                break;
            case 8:
                if (root) printf("Max: %d\n", maxValueNode(root)->key);
                else printf("Tree is empty\n");
                break;
            case 9:
                printf("Height (nodes): %d\n", height(root));
                break;
            case 0:
                freeTree(root);
                printf("Exiting...\n");
                return 0;
            default:
                printf("Invalid choice\n");
        }
    }

    return 0;
}
