```c
// Function to delete a node from BST
struct Node* deleteNode(struct Node* root, int key) {
    // Base case: if tree is empty
    if (root == NULL)
        return root;

    // If key to delete is smaller than root's key,
    // it lies in the left subtree
    if (key < root->key)
        root->left = deleteNode(root->left, key);

    // If key to delete is greater than root's key,
    // it lies in the right subtree
    else if (key > root->key)
        root->right = deleteNode(root->right, key);

    // If key is same as root's key — this is the node to delete
    else {
        // Case 1: Node has no left child
        if (root->left == NULL) {
            struct Node* temp = root->right;  // Save right child
            free(root);                       // Free current node
            return temp;                      // Return right child to link with parent
        } 
        // Case 2: Node has no right child
        else if (root->right == NULL) {
            struct Node* temp = root->left;   // Save left child
            free(root);                       // Free current node
            return temp;                      // Return left child to link with parent
        }

        // Case 3: Node has *two* children
        // Find inorder successor — smallest value in right subtree
        struct Node* temp = minValueNode(root->right);

        // Copy the inorder successor's key to this node
        root->key = temp->key;

        // Delete the inorder successor (which is now a duplicate)
        root->right = deleteNode(root->right, temp->key);
    }

    // Return (possibly updated) root pointer to parent
    return root;
}
```

